from calc1_core import *
import mpmath as mp
mp.mp.dps=60
D=CalcDoc('1.8',[92,93,94],lambda n:92 if n<=20 else 93 if n<=50 else 94)
def add(n,st,steps,ans,check,parts=()):return D.add(n,('연속성·중간값 정리','Continuity and the Intermediate Value Theorem'),st,('정의역과 함수값, 양쪽 극한을 먼저 확인한다. 중간값 정리는 닫힌 구간의 연속성을 요구한다.','First check the domain, assigned value, and two-sided limit. The Intermediate Value Theorem requires continuity on a closed interval.'),steps,ans,check,parts)
add(1,('f가 4에서 연속임을 하나의 등식으로 나타내라.','Express continuity of f at 4 as an equation.'),[('주변에서 접근하는 값이 실제 지정값과 같아야 한다.','The approached value must equal the assigned value.')],d(r'\lim_{x\to4}f(x)=f(4)'),('이 등식은 f(4)의 정의와 유한 극한의 존재를 모두 전제한다.','The equation requires both a defined f(4) and an existing finite limit.'))
add(2,('실수 전체에서 연속인 함수의 그래프는 어떤 성질을 갖는가?','What property does the graph of a function continuous on all real numbers have?'),[('모든 점에서 극한과 함수값이 일치하므로 구멍·점프·수직 발산에 의한 끊김이 없다.','At every point the limit agrees with the value, excluding holes, jumps, and breaks caused by vertical divergence.')],('그래프가 끊김 없이 이어진다. 모서리는 있을 수 있다.','The graph is unbroken; corners are still possible.'),('예를 들어 |x|는 0에서 모서리가 있어도 연속이므로 매끄러움까지 요구하지 않는다.','For example, |x| is continuous despite its corner at zero, so smoothness is not required.'))
add(3,('원본 f 그래프에는 −4에 빈 구멍, −2에 좌우 높이가 다른 두 조각(왼쪽 끝 닫힘), 2에 점프(오른쪽 시작 닫힘), 4에 왼쪽 −∞와 유한한 오른쪽 닫힌 시작점이 있다. (a)불연속점을 설명하고 (b)각 점의 한쪽 연속성을 분류하라.','The source f-graph has an unfilled hole at −4; a jump at −2 with the left endpoint filled; a jump at 2 with the right endpoint filled; and at 4 a left limit −∞ with a finite filled starting point on the right. (a)Explain the discontinuities and (b)classify one-sided continuity.'),[('−4는 값이 없어 어느 쪽으로도 연속이 아니다. −2는 지정값이 왼쪽 극한에만, 2와 4는 오른쪽 극한에만 일치한다.','At −4 the missing value prevents continuity from either side. At −2 the assigned value matches only the left limit; at 2 and 4 it matches only the right limit.')],('(a)−4,−2,2,4. (b)차례로 어느 쪽도 아님, 왼쪽, 오른쪽, 오른쪽.','(a)−4,−2,2,4. (b)Neither, left, right, right, respectively.'),('PDF129의 점 표시와 4의 왼쪽 발산을 따로 읽어 단순 점프와 무한 불연속을 구분했다.','Read the markers and the left divergence at 4 separately on PDF129, distinguishing jumps from infinite discontinuity.'),list('ab'))
add(4,('원본 g 그래프는 −2에 구멍, −1에서 양쪽 −∞, 0에서 서로 다른 좌우 높이, 1에서 서로 다른 좌우 높이와 별도 지정값을 갖는다. 불연속점을 이유와 함께 쓰라.','The source g-graph has a hole at −2, divergence to −∞ on both sides of −1, unequal one-sided heights at 0, and unequal one-sided heights with a separate assigned value at 1. Identify and explain its discontinuities.'),[('구멍에서는 값이 없고, 발산점에서는 유한 극한이 없으며, 두 점프에서는 공통 양쪽 극한이 없다.','The hole lacks an assigned value; the divergent point lacks a finite limit; both jumps lack a common two-sided limit.')],('−2:제거 가능; −1:무한; 0,1:점프 불연속.','−2:removable; −1:infinite; 0 and 1:jump discontinuities.'),('−3과 3은 그래프의 닫힌 정의역 끝점이며 정의역 내부 방향의 연속성을 가지므로 추가 불연속점으로 세지 않는다.','The filled domain endpoints −3 and 3 are continuous from within their domain and are not counted as additional discontinuities.'))
for n,bad,holes,description in [(5,[1],[3],('1에서 점프하고 3에서 극한 높이와 다른 닫힌 값이 있는 그래프','a graph with a jump at 1 and a reassigned value at a hole at 3')),(6,[1,5],[3],('1에서 양쪽 +∞이며 유한한 지정값이 있고, 3에 재지정된 구멍, 5에 점프가 있는 그래프','a graph with two-sided +∞ at 1 and a finite assigned value, a reassigned hole at 3, and a jump at 5'))]:
 add(n,('원본은 '+description[0]+'이다. (a)유한 극한이 없는 a, (b)불연속인 a, (c)극한은 있으나 불연속인 a를 구하라.','The source shows '+description[1]+'. Find (a)a with no finite limit, (b)all discontinuities, and (c)a where a limit exists but continuity fails.'),[('점프·발산은 유한 양쪽 극한을 없앤다. 지정값만 바뀐 구멍은 극한을 유지하지만 연속은 아니다.','Jumps and divergence prevent a finite two-sided limit. Reassigning a value at a hole preserves the limit but destroys continuity.')],('(a)'+str(bad)+'; (b)'+str(sorted(bad+holes))+'; (c)'+str(holes), '(a)'+str(bad)+'; (b)'+str(sorted(bad+holes))+'; (c)'+str(holes)),('축의 한 칸이 1임을 기준으로 문제별 불연속 위치를 독립적으로 판독했다.','Read each discontinuity position independently using the unit tick spacing.'),list('abc'))
construct=[(7,('−2에 제거 가능, 2에 무한 불연속','a removable discontinuity at −2 and an infinite discontinuity at 2'),r'f(x)=\begin{cases}1/(x-2)&x\notin\{-2,2\}\\0&x\in\{-2,2\}\end{cases}',('−2의 극한은 −1/4인데 값은 0이다. 2에서는 좌우 발산하나 f(2)=0으로 실수 전체에 정의했다.','The limit at −2 is −1/4 while its value is zero. At 2 the sides diverge, but f(2)=0 makes the function defined on all real numbers.'),[samples(lambda z:1/(z-2),-5,1.98),samples(lambda z:1/(z-2),2.02,5)],[(-2,-.25,'open'),(-2,0),(2,0)],(-5,5,-3,3)),(8,('−3에 점프, 4에 제거 가능 불연속','a jump at −3 and a removable discontinuity at 4'),r'f(x)=\begin{cases}0&x<-3\\2&x=4\\1&x\ge-3,\ x\ne4\end{cases}',('−3에서 좌 0·우 1이다. 4에서는 양쪽 극한 1과 지정값 2가 다르다.','At −3 the limits are 0 and 1. At 4 both limits are 1, differing from the assigned value 2.'),[[(-5,0),(-3,0)],[(-3,1),(6,1)]],[(-3,0,'open'),(-3,1),(4,1,'open'),(4,2)],(-5,6,-.5,2.5)),(9,('0과 3에서만 불연속이며 0에서 오른쪽, 3에서 왼쪽 연속','discontinuities only at 0 and 3, right-continuous at 0 and left-continuous at 3'),r'f(x)=\begin{cases}0&x<0\\1&0\le x\le3\\2&x>3\end{cases}',('0의 값은 오른쪽 조각 1이고, 3의 값은 왼쪽 조각 1이다.','The value at 0 matches the right piece 1, and the value at 3 matches the left piece 1.'),[[(-2,0),(0,0)],[(0,1),(3,1)],[(3,2),(5,2)]],[(0,0,'open'),(0,1),(3,1),(3,2,'open')],(-2,5,-.5,2.5)),(10,('−1에서는 왼쪽으로만 연속, 3에서는 어느 쪽으로도 연속이 아닌 불연속','a discontinuity at −1 continuous only from the left, and one at 3 continuous from neither side'),r'f(x)=\begin{cases}0&x\le-1\\2&x=3\\1&x>-1,\ x\ne3\end{cases}',('−1의 좌극한·값은 0이고 우극한은 1이다. 3의 좌우 극한은 1이지만 값은 2이다.','At −1 the left limit and value are zero, while the right limit is 1. At 3 both limits are 1 but the value is 2.'),[[(-3,0),(-1,0)],[(-1,1),(5,1)]],[(-1,0),(-1,1,'open'),(3,1,'open'),(3,2)],(-3,5,-.5,2.5))]
for n,require,formula,reason,cs,dots,bounds in construct:
 add(n,('실수 전체에 정의되고 '+require[0]+'을 가지며 나머지 점에서는 연속인 함수를 그리고 제시하라.','Construct and sketch a function defined on all real numbers with '+require[1]+', continuous elsewhere.'),[(d(formula),d(formula)),reason],('위 조각함수가 한 예이다.','The displayed piecewise function is one example.'),('각 조각 내부는 연속이고 모든 접합점·별도 지정점에서 요구된 극한과 함수값을 확인했다.','Every piece is continuous internally, and each junction or reassigned point has the required limits and values.'))
 D.fig(n,[panel('Constructed continuity example',bounds,cs,dots)])
add(11,('통행료는 보통 $5, 07–10시와 16–19시에는 $7이다. (a)자정 이후 시간 t의 함수로 그리고 (b)불연속과 이용자의 의미를 설명하라.','A toll is $5 normally and $7 during 07–10 and 16–19. (a)Graph it against hours t after midnight and (b)explain its discontinuities and their meaning for travelers.'),[('시작 시각 포함·종료 시각 제외로 정하면 T=7은 [7,10)∪[16,19), 나머지 [0,24)에서는 T=5이다.','Using start-inclusive, end-exclusive intervals, T=7 on [7,10)∪[16,19) and T=5 elsewhere in [0,24).'),('경계 7,10,16,19에서 $2의 점프가 있어 아주 작은 통과 시각 차이가 요금을 바꾼다.','There are $2 jumps at 7,10,16,19, so a tiny change in crossing time can change the charge.')],('불연속 시각:07:00,10:00,16:00,19:00.','Discontinuities:07:00,10:00,16:00,19:00.'),('정확한 경계 시각의 요금은 원문의 끝점 규정이 없어 선택을 명시했다. 어느 규정이어도 네 시각의 점프는 유지된다.','Because the source does not specify boundary-time charges, the convention is explicit. Either convention retains the same four jumps.'),list('ab'))
D.fig(11,[panel('Toll by hour after midnight',(0,24,4,8),[[(0,5),(7,5)],[(7,7),(10,7)],[(10,5),(16,5)],[(16,7),(19,7)],[(19,5),(24,5)]],[(7,5,'open'),(7,7),(10,7,'open'),(10,5),(16,5,'open'),(16,7),(19,7,'open'),(19,5)],xticks=[0,7,10,16,19,24],yticks=[5,7],xlabel='hour',ylabel='$')])
add(12,('다음 양의 연속성을 설명하라: (a)한 장소의 시간별 온도, (b)한 시각에 뉴욕에서 서쪽으로 이동한 거리별 온도, (c)같은 거리별 고도, (d)택시 거리별 요금, (e)방 조명 회로의 시간별 전류.','Discuss continuity of (a)temperature versus time at one location, (b)temperature versus westward distance from New York at one time, (c)altitude versus the same distance, (d)taxi fare versus distance, and (e)lighting-circuit current versus time.'),[('(a),(b)는 통상적인 연속 매질 모형에서 작은 시간·위치 변화가 작은 온도 변화로 이어져 연속으로 본다.','In the usual continuous-medium model, (a) and (b) are continuous because small time or position changes produce small temperature changes.'),('(c)는 절벽을 수직으로 이상화하면 고도가 점프할 수 있다. (d)는 일정 거리마다 요금이 가산되는 계단 모형에서 불연속이다.','For (c), an idealized vertical cliff can create a jump in altitude. In (d), a fare increased at distance thresholds is a discontinuous step function.'),('(e)는 이상적 스위치 모형에서 켜고 끄는 순간 전류가 점프한다. 실제 물리 전이는 유한 시간에 걸칠 수 있다.','In (e), an ideal switch model makes current jump when switched on or off; a physical transition can take a finite time.')],('(a),(b)통상 연속 모형; (c)절벽에서 불연속 가능; (d)요금 임계거리에서 점프; (e)이상적 스위치 시각에서 점프.','(a),(b)usually modeled continuously; (c)possible discontinuities at cliffs; (d)jumps at fare thresholds; (e)jumps at ideal switching times.'),('물리량 자체와 문제에서 쓰는 이상화된 모형의 연속성을 구분해, 임의의 실제 관측 자료까지 단정하지 않았다.','Distinguished the idealized textbook models from unrestricted claims about every physical observation.'),list('abcde'))
x=s.symbols('x',real=True)
for n,f,a in [(13,3*x*x+(x+2)**5,-1),(14,(x*x+5*x)/(2*x+1),2),(15,2*s.sqrt(3*x*x+1),1),(16,(4*x*x-2*x+7)**s.Rational(1,3),-2)]:
 L=s.simplify(f.subs(x,a))
 add(n,('정의와 극한 법칙으로 '+m('f(x)='+tex(f))+f'가 a={a}에서 연속임을 보여라.','Using the definition and limit laws, show that '+m('f(x)='+tex(f))+f' is continuous at a={a}.'),[('다항식·근호·몫의 극한 법칙으로 해당 입력을 대입한다. 분모는 0이 아니고 근호는 실수 정의역에 있다.','Apply polynomial, root, and quotient limit laws by substitution; denominators are nonzero and roots lie in their real domains.'),(d(r'\lim_{x\to'+str(a)+'}f(x)='+tex(L)+'=f('+str(a)+')'),d(r'\lim_{x\to'+str(a)+'}f(x)='+tex(L)+'=f('+str(a)+')'))],('연속이며 공통값은 '+m(tex(L))+'.','Continuous, with common value '+m(tex(L))+'.'),('원래 식의 함수값과 독립 기호 극한을 비교했다.','Compared direct evaluation of the original expression with an independent symbolic limit.'))
add(17,('f(x)=x+√(x−4)가 [4,∞)에서 연속임을 정의로 보여라.','Show from continuity and limit laws that f(x)=x+√(x−4) is continuous on [4,∞).'),[('a>4에서는 lim f(x)=a+√(a−4)=f(a)이다. 끝점에서는 오른쪽만 접근하여 lim(x→4⁺)f(x)=4=f(4)를 얻는다.','For a>4, lim f(x)=a+√(a−4)=f(a). At the endpoint use the right-hand limit, lim(x→4⁺)f(x)=4=f(4).')],('[4,∞)에서 연속.','Continuous on [4,∞).'),('x<4는 실수 근호의 정의역 밖이므로 끝점에 양쪽 극한을 요구하지 않는다.','Inputs x<4 are outside the real-root domain, so a two-sided endpoint limit is not required.'))
add(18,('g(x)=(x−1)/(3x+6)가 (−∞,−2)에서 연속임을 보여라.','Show that g(x)=(x−1)/(3x+6) is continuous on (−∞,−2).'),[('임의 a<−2에서 3a+6≠0이므로 몫 법칙으로 lim g(x)=(a−1)/(3a+6)=g(a)이다.','For any a<−2, 3a+6≠0, so the quotient law gives lim g(x)=(a−1)/(3a+6)=g(a).')],('(−∞,−2)에서 연속.','Continuous on (−∞,−2).'),('제외된 끝점 −2에서는 분모가 0이므로 주어진 열린 구간의 조건이 필요하다.','At the excluded endpoint −2 the denominator is zero, confirming the relevance of the open interval.'))
for n in [19,20]:
 add(n,('함수 '+m(r'f(x)=1/(x+2)')+('에 대해 a=−2에서 불연속인 이유를 설명하고 그려라.'if n==19 else'를 x≠−2에 사용하고 f(−2)=1로 정한다. −2에서 불연속인 이유를 설명하고 그려라.'),'Use '+m(r'f(x)=1/(x+2)')+(' and explain its discontinuity at −2; sketch the graph.'if n==19 else' for x≠−2 and set f(−2)=1. Explain the discontinuity at −2 and sketch the graph.')),[(d(r'\lim_{x\to-2^-}f(x)=-\infty,\quad\lim_{x\to-2^+}f(x)=+\infty'),d(r'\lim_{x\to-2^-}f(x)=-\infty,\quad\lim_{x\to-2^+}f(x)=+\infty')),('유한 양쪽 극한이 없어 한 점의 값으로 연속성을 만들 수 없다.','There is no finite two-sided limit, so no single-point assignment can make the function continuous.')],('−2에서 무한 불연속.','Infinite discontinuity at −2.'),('분자는 양수 1, 분모는 접근 방향에 따라 부호가 달라지는 작은 수이므로 두 발산 방향을 확인할 수 있다.','The positive numerator 1 divided by a small denominator of opposite signs confirms both divergence directions.'))
 D.fig(n,[panel('Reciprocal with vertical asymptote',(-5,2,-5,5),[samples(lambda z:1/(z+2),-5,-2.01),samples(lambda z:1/(z+2),-1.99,2)],[]if n==19 else[(-2,1)])])
disc=[(21,r'\begin{cases}1-x^2&x<1\\1/x&x\ge1\end{cases}',1,('왼쪽 극한 0, 오른쪽 극한과 함수값 1로 점프한다.','The left limit is 0 while the right limit and value are 1, giving a jump.'),[samples(lambda z:1-z*z,-2,1),samples(lambda z:1/z,1,4)],[(1,0,'open'),(1,1)],(-2,4,-3,2)),(22,r'\begin{cases}(x^2-x)/(x^2-1)&x\ne1\\1&x=1\end{cases}',1,('x≠±1에서 f=x/(x+1)이므로 극한은 1/2이나 f(1)=1이다.','For x≠±1, f=x/(x+1), so the limit is 1/2 while f(1)=1.'),[samples(lambda z:z/(z+1),-3,-1.01),samples(lambda z:z/(z+1),-.99,3)],[(1,.5,'open'),(1,1)],(-3,3,-3,4)),(23,r'\begin{cases}\cos x&x<0\\0&x=0\\1-x^2&x>0\end{cases}',0,('두 한쪽 극한은 1이지만 f(0)=0이다.','Both one-sided limits are 1, but f(0)=0.'),[samples(math.cos,-3,0),samples(lambda z:1-z*z,0,2)],[(0,1,'open'),(0,0)],(-3,2,-3,2)),(24,r'\begin{cases}(2x^2-5x-3)/(x-3)&x\ne3\\6&x=3\end{cases}',3,('분자=(x−3)(2x+1)이므로 극한은 7, 지정값은 6이다.','The numerator is (x−3)(2x+1), so the limit is 7 while the assigned value is 6.'),[samples(lambda z:2*z+1,1,5)],[(3,7,'open'),(3,6)],(1,5,2,12))]
for n,form,a,reason,cs,dots,bounds in disc:
 add(n,('함수 '+d('f(x)='+form)+f'가 a={a}에서 불연속인 이유를 설명하고 그려라.','For '+d('f(x)='+form)+f', explain the discontinuity at a={a} and sketch the graph.'),[reason,('연속성에는 존재하는 양쪽 극한이 실제 함수값과 같아야 한다.','Continuity requires an existing two-sided limit equal to the assigned value.')],('점프 불연속.'if n==21 else'제거 가능 불연속.','Jump discontinuity.'if n==21 else'Removable discontinuity.'),('열린 점에는 접근값, 닫힌 점에는 지정값을 표시했다.'+('22번 원식은 −1에서도 정의되지 않으며 그 점근선도 그래프에 보존했다.'if n==22 else''),'Open points show approached values and filled points show assignments.'+(' In 22 the original expression is also undefined at −1; its asymptote is retained in the graph.'if n==22 else'')))
 D.fig(n,[panel('Assigned value versus limit',bounds,cs,dots)])
for n,form,g,L in [(25,r'\frac{x-3}{x^2-9}',r'\frac1{x+3}',s.Rational(1,6)),(26,r'\frac{x^2-7x+12}{x-3}',r'x-4',-1)]:
 add(n,('f(x)='+m(form)+'에 대해 (a)3의 불연속이 제거 가능함을 보이고 (b)연속이 되도록 f(3)을 정하라.','For f(x)='+m(form)+', (a)show that the discontinuity at 3 is removable and (b)assign f(3) to make it continuous there.'),[('x≠3에서 인수 (x−3)를 약분하면 '+m(g)+'이다.','Cancel the factor (x−3) for x≠3 to obtain '+m(g)+'.'),('이 식의 3에서 극한은 '+m(tex(L))+'로 유한하다.','Its limit at 3 is finite and equals '+m(tex(L))+'.')],d('f(3)='+tex(L)),('이 값만이 기존의 뚫린 근방 극한과 일치하므로 유일한 연속 재정의이다.'+('−3의 다른 특이점까지 제거하는 것은 아니다.'if n==25 else''),'This is the unique assignment agreeing with the existing punctured-neighborhood limit.'+(' It does not remove the other singularity at −3.'if n==25 else'')),list('ab'))
domains=[(27,r'\frac{x^2}{\sqrt{x^4+2}}',r'\mathbb R','x⁴+2≥2이므로 근호 분모가 항상 양수이다.','The radicand x⁴+2≥2 makes the denominator always positive.'),(28,r'\frac{3x-1}{x^2+2x-15}',r'\mathbb R\setminus\{-5,3\}','분모=(x+5)(x−3)이므로 −5,3을 제외한다.','The denominator factors as (x+5)(x−3), excluding −5 and 3.'),(29,r'\frac{\cos(x^2)}{1-x^2}',r'\mathbb R\setminus\{-1,1\}','cos(x²)는 연속이고 분모는 ±1에서만 0이다.','The composition cos(x²) is continuous and the denominator vanishes only at ±1.'),(30,r'\frac1x-\frac{x^2}{x-2}',r'\mathbb R\setminus\{0,2\}','두 유리식의 공통 정의역은 0과 2를 제외한 실수이다.','The common domain of the rational terms excludes 0 and 2.'),(31,r'x\sqrt{9-x^2}',r'[-3,3]','9−x²≥0을 풀면 −3≤x≤3이다.','Solving 9−x²≥0 gives −3≤x≤3.'),(32,r'\sqrt{3x-2}+\sqrt[3]{2x-3}',r'[2/3,\infty)','제곱근은 x≥2/3, 실수 세제곱근은 모든 x에서 정의된다.','The square root requires x≥2/3; the real cube root is defined for every x.'),(33,r'\sqrt{1+1/x}',r'(-\infty,-1]\cup(0,\infty)','(x+1)/x≥0이며 x≠0이어야 하므로 부호표로 두 구간을 얻는다.','Require (x+1)/x≥0 and x≠0; a sign chart gives the two intervals.'),(34,r'\sin(\cos(\sin x))',r'\mathbb R','사인과 코사인은 실수 전체에서 연속이며 세 합성 모두 정의된다.','Sine and cosine are continuous on all real numbers and every stage of the composition is defined.')]
for n,form,dom,ko,en in domains:
 add(n,('함수 '+m('f(x)='+form)+'의 정의역을 쓰고 정의역의 모든 점에서 연속인 이유를 설명하라.','State the domain of '+m('f(x)='+form)+' and explain why it is continuous at every point of that domain.'),[(ko,en),('연속인 기본함수의 합·곱·몫(분모≠0)·합성은 그 정의역에서 연속이다.','Sums, products, quotients with nonzero denominators, and compositions of continuous basic functions are continuous on their domains.')],d('D='+dom),('분모의 영점과 짝수근의 부등식을 먼저 처리하여 연속성 법칙을 정의역 밖에 적용하지 않았다. 끝점은 정의역 내 한쪽 연속성을 뜻한다.','Resolved denominator zeros and even-root inequalities before applying continuity laws. At a domain endpoint, continuity is from within the domain.'))
lims=[(35,x*s.sqrt(20-x*x),2,8),(36,s.sin(s.tan(s.cos(x))),s.pi/2,0),(37,x*x*s.tan(x),s.pi/4,s.pi**2/16),(38,x**3/s.sqrt(x*x+x-2),2,4)]
for n,f,a,L in lims:
 add(n,('연속성을 이용해 '+d(r'\lim_{x\to'+tex(a)+'}'+tex(f))+'을 구하라.','Use continuity to evaluate '+d(r'\lim_{x\to'+tex(a)+'}'+tex(f))),[('접근점에서 모든 구성함수가 정의되고 분모는 0이 아니므로 직접 대입할 수 있다.','Every component is defined at the approach point and any denominator is nonzero, so direct substitution is valid.'),(d('f('+tex(a)+')='+tex(L)),d('f('+tex(a)+')='+tex(L)))],d(tex(L)),('근호 내부·탄젠트 입력을 단계별로 대입해 합성 중 숨은 특이점이 없음을 확인했다.','Evaluated the radicands and tangent inputs stage by stage to check for hidden singularities in the composition.'))
add(39,('f(x)=1/√(1−sin x)의 불연속 위치를 구하고 그려라.','Locate the discontinuities of f(x)=1/√(1−sin x) and plot it.'),[('1−sin x≥0이지만 분모이므로 0인 점은 제외한다. sin x=1의 해는 π/2+2kπ이다.','Although 1−sin x≥0, its zeros must be excluded because the root is a denominator. The solutions of sin x=1 are π/2+2kπ.'),('각 제외점의 양쪽에서 양의 분모가 0으로 가므로 +∞로 발산한다.','On both sides of each excluded point, the positive denominator approaches zero and the function tends to +∞.')],d(r'x=\pi/2+2k\pi,\quad k\in\mathbb Z'),('항등식 1−sin(a+h)=1−cos h=2sin²(h/2)로 점근선 근처의 양의 발산을 확인한다.','The identity 1−sin(a+h)=1−cos h=2sin²(h/2) confirms positive divergence near each asymptote.'))
cuts=[-2*math.pi,-3*math.pi/2,math.pi/2,2*math.pi]
D.fig(39,[panel('Reciprocal square root of 1 - sin x',(-2*math.pi,2*math.pi,0,8),[samples(lambda z:1/math.sqrt(1-math.sin(z)),a+.005,b-.005)for a,b in zip(cuts,cuts[1:])])])
add(40,('y=tan√x의 불연속 위치를 찾고 그래프를 그려라.','Locate the discontinuities of y=tan√x and plot the graph.'),[('x≥0이 필요하다. √x=π/2+kπ에서 탄젠트가 정의되지 않으며 √x≥0이므로 k=0,1,2,…이다.','The square root requires x≥0. Tangent fails at √x=π/2+kπ; since √x≥0, k=0,1,2,….'),('나머지 정의역에서는 합성 연속이고 x=0에서도 오른쪽으로 연속이다.','The composition is continuous elsewhere in its domain and is right-continuous at x=0.')],d(r'x=(\pi/2+k\pi)^2,\quad k=0,1,2,\ldots'),('제곱으로 생길 수 있는 중복 해를 k≥0으로 제거했다. 음의 x는 정의역 밖이며 불연속점으로 별도 열거하지 않는다.','Restricting k≥0 removes duplicates from squaring. Negative x lies outside the domain and is not separately listed as a discontinuity.'))
